select coalesce(json_agg(json_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'language',l.lanname,'security_definer',p.prosecdef,'volatility',p.provolatile,'owner',pg_get_userbyid(p.proowner)) order by n.nspname,p.proname),'[]'::json) as data from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e');
